const QCM = [
// ---------- Bases et MLP ----------
{c:"mlp",q:"Un modèle linéaire généralisé (GLM) pour une classification binaire calcule :",o:["$\\sigma(w^\\top x + b)$","$w^\\top x + b$ sans transformation","$\\max(0, w^\\top x)$","une moyenne des $x_j$"],a:0,e:"La régression logistique est un GLM : une combinaison linéaire passée dans une fonction de lien inverse (la sigmoïde). Un MLP généralise cette idée avec des couches cachées."},
{c:"mlp",q:"Sans fonction d'activation non linéaire, un MLP de 10 couches équivaut à :",o:["un réseau très expressif","une seule transformation affine","un arbre de décision","un réseau convolutif"],a:1,e:"Une composition de fonctions affines reste affine. La non-linéarité est ce qui donne de l'expressivité aux couches empilées."},
{c:"mlp",q:"Une couche Linear(100, 6) de PyTorch contient combien de paramètres ?",o:["600","606","106","6"],a:1,e:"100 × 6 poids + 6 biais = 606."},
{c:"mlp",q:"Le théorème d'approximation universelle dit qu'un réseau à une couche cachée :",o:["s'entraîne toujours jusqu'à l'optimum global","peut approcher toute fonction continue sur un compact, avec assez de neurones","a besoin de moins de neurones qu'un réseau profond","garantit une bonne généralisation"],a:1,e:"C'est un résultat d'existence : il ne dit ni combien de neurones il faut, ni comment les apprendre, ni si le modèle généralisera."},
{c:"mlp",q:"Pourquoi utilise-t-on des réseaux profonds si une seule couche cachée suffit en théorie ?",o:["La profondeur rend le calcul plus rapide","Les réseaux profonds représentent certaines fonctions avec beaucoup moins de paramètres","Une couche cachée ne peut pas utiliser ReLU","La profondeur supprime le surapprentissage"],a:1,e:"La profondeur permet des représentations hiérarchiques et compositionnelles, souvent bien plus économes qu'une couche très large."},
{c:"mlp",q:"La passe avant (forward) d'un réseau sert à :",o:["calculer les gradients","calculer la sortie et la perte à partir de l'entrée","mettre à jour les poids","normaliser les données"],a:1,e:"Forward : entrée vers sortie puis perte. Backward : gradients de la perte par rapport aux paramètres, par la règle de dérivation en chaîne."},
{c:"mlp",q:"La rétropropagation (backpropagation) repose sur :",o:["la règle de dérivation en chaîne","le tirage aléatoire des poids","l'inversion de la matrice hessienne","des différences finies sur chaque poids"],a:0,e:"Elle propage les dérivées de la sortie vers l'entrée en réutilisant les résultats intermédiaires de la passe avant."},
{c:"mlp",q:"Pour une classification à K classes, la sortie du réseau passe généralement par :",o:["une sigmoïde par classe puis une somme","un softmax, avec une perte d'entropie croisée","une ReLU","une tangente hyperbolique"],a:1,e:"Softmax transforme les scores (logits) en probabilités. En PyTorch, CrossEntropyLoss applique le log-softmax lui-même : on lui donne les logits bruts."},
{c:"mlp",q:"En PyTorch, nn.CrossEntropyLoss attend en entrée :",o:["des probabilités après softmax","des logits bruts et des labels entiers (int64)","des labels en one-hot float","des logits et des labels float"],a:1,e:"Appliquer un softmax avant CrossEntropyLoss revient à le faire deux fois. Les labels sont des indices de classe en int64."},
{c:"mlp",q:"La fonction ReLU est définie par :",o:["$1/(1+e^{-x})$","$\\max(0, x)$","$\\tanh(x)$","$x^2$"],a:1,e:"ReLU est simple, peu coûteuse, et sa dérivée vaut 1 pour x > 0, ce qui limite la disparition du gradient."},
{c:"mlp",q:"Un inconvénient de la sigmoïde dans les couches cachées profondes :",o:["elle n'est pas dérivable","sa dérivée est au plus 0,25, ce qui fait s'évanouir le gradient","elle sort des valeurs négatives","elle est trop rapide à calculer"],a:1,e:"Le produit de nombreuses dérivées inférieures à 0,25 fait tendre le gradient vers 0 dans les premières couches."},
{c:"mlp",q:"Pourquoi le deep learning a-t-il décollé autour de 2012 ?",o:["Invention de la rétropropagation en 2012","Combinaison de grands jeux de données, de GPU et de meilleures méthodes et logiciels","Abandon des fonctions d'activation","Fin des réseaux convolutifs"],a:1,e:"La rétropropagation date des années 1980. Ce qui a changé : les données (ImageNet), le calcul (GPU) et des astuces d'entraînement (ReLU, dropout, initialisation)."},
{c:"mlp",q:"Pour un MLP sur des images 28 × 28 en niveaux de gris, la première couche reçoit :",o:["une matrice 28 × 28 telle quelle","un vecteur de 784 valeurs (image aplatie)","28 vecteurs indépendants","3 canaux"],a:1,e:"Le MLP aplatit l'image. Il perd la structure spatiale, ce qui motive les réseaux convolutifs."},
{c:"mlp",q:"Un problème du MLP sur les images, que les CNN corrigent :",o:["il ne peut pas classer d'images","il n'exploite ni la localité ni le partage de poids, d'où énormément de paramètres","il ne supporte pas la descente de gradient","il n'a pas de biais"],a:1,e:"Chaque pixel est connecté à chaque neurone. Les CNN utilisent des filtres locaux partagés sur toute l'image."},

// ---------- Optimisation ----------
{c:"opt",q:"La mise à jour de la descente de gradient est :",o:["$w \\leftarrow w + \\eta \\nabla L$","$w \\leftarrow w - \\eta \\nabla L$","$w \\leftarrow \\eta w$","$w \\leftarrow w - L$"],a:1,e:"On se déplace dans la direction opposée au gradient, avec un pas η (taux d'apprentissage)."},
{c:"opt",q:"La descente de gradient stochastique (SGD) par mini-batch :",o:["calcule le gradient exact sur tout le jeu de données","estime le gradient sur un petit sous-ensemble à chaque pas","n'utilise pas de gradient","ne fonctionne qu'avec un batch de 1"],a:1,e:"Le gradient du mini-batch est un estimateur sans biais du gradient complet, bruité mais beaucoup moins coûteux."},
{c:"opt",q:"Un taux d'apprentissage trop grand provoque typiquement :",o:["une loss qui baisse très lentement","une loss qui oscille ou explose","un surapprentissage immédiat","aucun effet"],a:1,e:"Les pas dépassent le minimum. À l'inverse, un taux trop petit donne une convergence très lente."},
{c:"opt",q:"Le momentum :",o:["accumule une moyenne des gradients passés pour lisser et accélérer la descente","remet les poids à zéro","augmente la taille du batch","remplace la fonction de perte"],a:0,e:"Il réduit les oscillations dans les directions à forte courbure et accélère dans les directions constantes."},
{c:"opt",q:"Adam combine :",o:["momentum et un pas adaptatif par paramètre (moyenne des gradients au carré)","dropout et batch norm","SGD et recherche exhaustive","deux réseaux en compétition"],a:0,e:"Adam suit une moyenne mobile du gradient (moment 1) et du gradient au carré (moment 2), et divise le premier par la racine du second."},
{c:"opt",q:"Pourquoi Adam applique-t-il une correction de biais lors des premières itérations ?",o:["Parce que les moyennes mobiles initialisées à 0 sont biaisées vers 0 au début","Pour éviter le surapprentissage","Pour accélérer la fin de l'entraînement","Parce que le gradient est toujours positif"],a:0,e:"Avec $m_0 = 0$, $m_t$ sous-estime le gradient au début. On corrige par $\\hat m_t = m_t/(1-\\beta_1^t)$, idem pour le second moment."},
{c:"opt",q:"Que vaut le facteur de correction $1-\\beta_1^t$ pour $\\beta_1 = 0{,}9$ à $t = 1$ ?",o:["0,9","0,1","1","0,01"],a:1,e:"$1 - 0{,}9 = 0{,}1$ : on divise donc $m_1$ par 0,1, ce qui compense exactement l'initialisation à 0."},
{c:"opt",q:"Un epoch correspond à :",o:["une mise à jour des poids","un passage complet sur le jeu d'entraînement","un mini-batch","une évaluation sur le test"],a:1,e:"Avec N exemples et un batch de B, un epoch compte environ N/B mises à jour."},
{c:"opt",q:"Dans une boucle PyTorch, l'ordre correct est :",o:["loss.backward(), optimizer.zero_grad(), optimizer.step()","optimizer.zero_grad(), loss.backward(), optimizer.step()","optimizer.step(), loss.backward()","loss.backward() suffit"],a:1,e:"On remet les gradients à zéro (sinon ils s'accumulent), on les calcule, puis on met à jour les poids."},
{c:"opt",q:"Que se passe-t-il si on oublie optimizer.zero_grad() ?",o:["Rien","Les gradients de plusieurs batchs s'additionnent, les mises à jour sont fausses","Les poids sont remis à zéro","L'entraînement s'arrête avec une erreur"],a:1,e:"PyTorch accumule les gradients par défaut dans .grad."},
{c:"opt",q:"Pourquoi normalise-t-on (standardise-t-on) les entrées ?",o:["Pour réduire la taille du dataset","Pour que les variables aient des échelles comparables et que l'optimisation soit mieux conditionnée","Pour supprimer les valeurs aberrantes","Pour rendre les données linéaires"],a:1,e:"Des échelles très différentes allongent la surface de perte et ralentissent la descente."},
{c:"opt",q:"Les statistiques de normalisation (moyenne, écart-type) doivent être calculées sur :",o:["l'ensemble des données","le jeu d'entraînement uniquement","le jeu de test","chaque batch de test"],a:1,e:"Les calculer sur la validation ou le test fait fuiter de l'information : c'est une fuite de données (data leakage)."},
{c:"opt",q:"La batch normalization normalise chaque caractéristique :",o:["sur les exemples du mini-batch","sur les caractéristiques d'un même exemple","sur tout le dataset une fois pour toutes","sur les poids"],a:0,e:"Batch norm : moyenne et variance sur le batch. Layer norm (utilisée dans les Transformers) : sur les caractéristiques d'un seul exemple."},
{c:"opt",q:"Pourquoi model.eval() est-il important au moment de l'évaluation ?",o:["Il désactive le calcul des gradients","Il fait passer dropout et batch norm en mode inférence","Il charge les meilleurs poids","Il accélère le GPU"],a:1,e:"En mode eval, le dropout est coupé et batch norm utilise ses statistiques globales. Pour couper les gradients, on utilise torch.no_grad()."},
{c:"opt",q:"Le dropout :",o:["supprime définitivement des neurones","met aléatoirement à zéro des activations pendant l'entraînement pour régulariser","réduit le taux d'apprentissage","double la taille du réseau"],a:1,e:"Il empêche la co-adaptation des neurones. Il est désactivé à l'inférence."},

// ---------- CNN ----------
{c:"cnn",q:"L'idée d'un filtre convolutif « invariant par position » est :",o:["un poids différent par pixel","les mêmes poids appliqués à toutes les positions de l'image","un filtre par classe","un filtre de la taille de l'image"],a:1,e:"Le partage de poids réduit fortement le nombre de paramètres et rend la détection d'un motif équivariante par translation."},
{c:"cnn",q:"Localité, en CNN, signifie que :",o:["chaque neurone ne regarde qu'une petite région de l'entrée","le réseau ne fonctionne que sur de petites images","les poids sont locaux au GPU","la sortie est locale à une classe"],a:0,e:"Cette petite région est le champ récepteur du neurone ; il grandit avec la profondeur."},
{c:"cnn",q:"Taille de sortie d'une convolution : entrée n = 28, noyau k = 5, padding p = 0, stride s = 1 ?",o:["28","24","23","14"],a:1,e:"$\\lfloor (n + 2p - k)/s \\rfloor + 1 = (28 - 5)/1 + 1 = 24$."},
{c:"cnn",q:"Même question avec n = 32, k = 3, p = 1, s = 2 :",o:["16","15","32","17"],a:0,e:"$\\lfloor (32 + 2 - 3)/2 \\rfloor + 1 = \\lfloor 15{,}5 \\rfloor + 1 = 16$."},
{c:"cnn",q:"Nombre de paramètres de Conv2d(3, 16, kernel_size=3) avec biais :",o:["144","432","448","160"],a:2,e:"$(3 \\times 3 \\times 3 + 1) \\times 16 = 28 \\times 16 = 448$."},
{c:"cnn",q:"Le padding sert principalement à :",o:["augmenter le nombre de canaux","contrôler la taille spatiale de la sortie et traiter les bords","réduire le surapprentissage","accélérer le calcul"],a:1,e:"Avec k = 3 et p = 1 (stride 1), la taille spatiale est conservée."},
{c:"cnn",q:"Après Conv2d(1, 4, 5) sur une image 28 × 28 puis un MaxPool2d(2, 2), combien de valeurs entrent dans la couche linéaire ?",o:["576","784","2 304","144"],a:0,e:"Conv : 4 cartes de 24 × 24. Pooling : 4 × 12 × 12 = 576."},
{c:"cnn",q:"Le max pooling 2 × 2 :",o:["apprend des poids","divise la hauteur et la largeur par 2 en gardant le maximum de chaque fenêtre","double la résolution","ajoute des canaux"],a:1,e:"Il n'a pas de paramètres. Il réduit la résolution et apporte une petite tolérance aux décalages."},
{c:"cnn",q:"Une architecture CNN typique de classification enchaîne :",o:["des couches linéaires puis des convolutions","des blocs convolution, activation, pooling, puis des couches linéaires en sortie","uniquement du pooling","une seule convolution géante"],a:1,e:"La résolution spatiale baisse et le nombre de canaux augmente au fil des blocs, puis une tête linéaire classe."},
{c:"cnn",q:"Le bloc résiduel de ResNet calcule :",o:["$F(x)$","$F(x) + x$","$F(x) \\cdot x$","$x - F(x)$"],a:1,e:"La connexion identité facilite la circulation du gradient et rend facile l'apprentissage d'une fonction proche de l'identité."},
{c:"cnn",q:"Pourquoi ResNet permet-il d'entraîner des réseaux très profonds ?",o:["Il supprime les non-linéarités","Les connexions résiduelles évitent la dégradation et laissent passer le gradient","Il utilise moins de données","Il n'a pas besoin de normalisation"],a:1,e:"Sans elles, ajouter des couches pouvait dégrader même l'erreur d'entraînement."},
{c:"cnn",q:"Le U-Net est caractérisé par :",o:["un encodeur sans décodeur","un encodeur, un décodeur et des connexions de saut qui concatènent les cartes de même résolution","uniquement des couches linéaires","une récurrence temporelle"],a:1,e:"Les connexions de saut restituent les détails fins perdus à l'encodage. Usage : segmentation, traduction d'images, débruiteur en diffusion."},
{c:"cnn",q:"Remplacer un noyau k × k par un noyau k × 1 suivi d'un noyau 1 × k (noyau de rang faible) :",o:["augmente les paramètres","fait passer de $k^2$ à $2k$ poids par filtre","supprime la non-linéarité","change la taille de sortie"],a:1,e:"C'est une approximation de rang 1 du noyau : moins de paramètres et de calculs."},
{c:"cnn",q:"Empiler deux convolutions 3 × 3 (stride 1) donne un champ récepteur de :",o:["3 × 3","5 × 5","6 × 6","9 × 9"],a:1,e:"Chaque couche 3 × 3 ajoute 2 pixels : 3 + 2 = 5."},
{c:"cnn",q:"La convolution est équivariante par translation, cela signifie :",o:["décaler l'entrée décale la carte de sortie de la même façon","la sortie ne change jamais","le réseau ignore la position","les poids changent avec la position"],a:0,e:"L'invariance (sortie identique) s'obtient en partie avec le pooling et l'agrégation finale."},
{c:"cnn",q:"Le nombre de canaux de sortie d'une couche convolutive correspond :",o:["à la taille du noyau","au nombre de filtres appris","au stride","à la taille du batch"],a:1,e:"Chaque filtre produit une carte d'activation."},

// ---------- RNN ----------
{c:"rnn",q:"Un RNN simple met à jour son état caché par :",o:["$h_t = f(W x_t + U h_{t-1} + b)$","$h_t = W x_t$","$h_t = h_{t-1}$","$h_t = \\text{softmax}(x_t)$"],a:0,e:"Les mêmes poids W et U sont réutilisés à chaque pas de temps."},
{c:"rnn",q:"La rétropropagation à travers le temps (BPTT) :",o:["déplie le réseau dans le temps et rétropropage sur la séquence entière","entraîne chaque pas séparément","n'utilise pas de gradient","ne s'applique qu'aux CNN"],a:0,e:"C'est le mode inverse de la dérivation, appliqué au graphe déplié."},
{c:"rnn",q:"Real-Time Recurrent Learning (RTRL) et BPTT :",o:["donnent des gradients différents","calculent le même gradient, RTRL en avançant dans le temps, au prix d'un coût mémoire et calcul bien plus élevé","sont deux architectures de réseau","ne s'appliquent qu'aux LSTM"],a:1,e:"RTRL est le mode direct (forward) : il permet un apprentissage en ligne mais coûte cher. BPTT est le mode inverse, bien moins coûteux."},
{c:"rnn",q:"Pourquoi le gradient s'évanouit-il dans un RNN simple sur de longues séquences ?",o:["Le réseau a trop peu de données","Il est le produit de nombreux facteurs souvent inférieurs à 1","Le softmax est mal défini","Les poids changent à chaque pas"],a:1,e:"À l'inverse, des facteurs supérieurs à 1 font exploser le gradient. L'arithmétique en virgule flottante aggrave le problème (sous-dépassement)."},
{c:"rnn",q:"Une parade simple contre l'explosion du gradient :",o:["le gradient clipping (écrêtage de la norme)","augmenter le taux d'apprentissage","retirer le biais","utiliser une sigmoïde"],a:0,e:"On rabaisse le gradient quand sa norme dépasse un seuil."},
{c:"rnn",q:"La cellule mémoire du LSTM sert à :",o:["stocker les labels","transporter l'information sur de longues durées avec peu de transformations","remplacer l'état caché","normaliser les entrées"],a:1,e:"Mise à jour quasi additive de c, contrôlée par des portes : le gradient circule beaucoup mieux."},
{c:"rnn",q:"Les trois portes d'un LSTM sont :",o:["entrée, oubli, sortie","reset, update, sortie","query, key, value","encodeur, décodeur, attention"],a:0,e:"Le GRU a deux portes : reset et update."},
{c:"rnn",q:"nn.LSTM de PyTorch renvoie :",o:["output, h_n","output, (h_n, c_n)","(output, h_n), c_n","h_n seulement"],a:1,e:"Le GRU renvoie output, h_n (pas de cellule c)."},
{c:"rnn",q:"Avec batch_first=True, pour un LSTM à 1 couche unidirectionnel, h_n a la forme :",o:["(batch, seq, hidden)","(1, batch, hidden)","(batch, hidden, 1)","(seq, hidden)"],a:1,e:"h_n est toujours (num_layers × directions, batch, hidden), même avec batch_first=True. D'où h_n[-1] pour la dernière couche."},
{c:"rnn",q:"Nombre de paramètres de nn.GRU(9, 100) :",o:["11 100","33 300","44 400","30 000"],a:1,e:"$3 \\times (100 \\times 9 + 100 \\times 100 + 2 \\times 100) = 3 \\times 11\\,100 = 33\\,300$ (PyTorch a deux biais par porte)."},
{c:"rnn",q:"Nombre de paramètres de nn.LSTM(9, 100) :",o:["33 300","44 400","11 100","40 000"],a:1,e:"4 blocs (3 portes et le candidat) × 11 100 = 44 400."},
{c:"rnn",q:"Le GRU par rapport au LSTM :",o:["a plus de paramètres","est une variante simplifiée, sans cellule mémoire séparée, avec 2 portes","n'a pas de portes","ne peut pas traiter de séquences"],a:1,e:"Il fusionne cellule et état caché : environ 3/4 des paramètres du LSTM."},
{c:"rnn",q:"Un RNN bidirectionnel :",o:["lit la séquence deux fois dans le même sens","combine une lecture gauche-droite et une lecture droite-gauche","prédit deux sorties","n'a pas d'état caché"],a:1,e:"Utile quand toute la séquence est connue, par exemple pour savoir si un mot est un verbe d'après le contexte des deux côtés."},
{c:"rnn",q:"Dans le TP4-2 (nom ou verbe), la couche de sortie d'un GRU bidirectionnel avec hidden = 100 est :",o:["Linear(100, 1)","Linear(200, 1)","Linear(50, 1)","Linear(100, 2)"],a:1,e:"Les états avant et arrière (100 + 100) sont concaténés. Une seule sortie avec BCEWithLogitsLoss."},
{c:"rnn",q:"pack_padded_sequence sert à :",o:["compresser les poids","ne pas faire traiter le padding par le RNN quand les séquences ont des longueurs différentes","augmenter la taille des séquences","trier les labels"],a:1,e:"Sans packing, l'état final d'une phrase courte aurait été modifié par les zéros de remplissage."},
{c:"rnn",q:"Une tâche « many to one » correspond à :",o:["traduire une phrase","classer une séquence entière (par exemple une activité)","étiqueter chaque mot","générer un texte"],a:1,e:"TP4-1 : une fenêtre de 128 pas donne une activité. L'étiquetage mot par mot est « many to many »."},
{c:"rnn",q:"Prédire un mot manquant au milieu d'une phrase favorise :",o:["un RNN unidirectionnel","un modèle bidirectionnel","un CNN 2D","un MLP sans contexte"],a:1,e:"Le contexte des deux côtés est informatif. C'est aussi l'idée du MLM de BERT."},

// ---------- Autoencodeurs et VAE ----------
{c:"ae",q:"Un autoencodeur est entraîné à :",o:["classer les images","reconstruire son entrée en passant par une représentation compressée","générer du texte","prédire le futur"],a:1,e:"Encodeur vers code latent de petite dimension, puis décodeur vers reconstruction. Perte : erreur de reconstruction."},
{c:"ae",q:"Le goulot d'étranglement (bottleneck) d'un autoencodeur :",o:["accélère l'entraînement","force le réseau à ne garder que l'information essentielle","supprime la non-linéarité","sert de couche de sortie"],a:1,e:"Sans contrainte, le réseau pourrait apprendre l'identité sans rien extraire."},
{c:"ae",q:"La convolution transposée sert à :",o:["réduire la résolution","augmenter la résolution spatiale (sur-échantillonner) de façon apprise","calculer un softmax","normaliser les cartes"],a:1,e:"Elle est utilisée dans les décodeurs et les générateurs. Effet secondaire connu : des artefacts en damier."},
{c:"ae",q:"Pourquoi ne peut-on pas générer de bonnes images en tirant des codes au hasard dans l'espace latent d'un autoencodeur classique ?",o:["Le décodeur n'existe pas","L'espace latent n'est pas organisé : des codes au hasard tombent dans des zones jamais vues","Les codes sont toujours nuls","Le code est trop grand"],a:1,e:"Le VAE corrige cela en imposant une distribution a priori (souvent N(0, I)) sur le latent."},
{c:"ae",q:"Dans un VAE, l'encodeur produit :",o:["un code unique","les paramètres d'une distribution (moyenne et variance) sur le code latent","une image","une probabilité de classe"],a:1,e:"On échantillonne z dans $q(z|x) = \\mathcal{N}(\\mu(x), \\sigma^2(x))$."},
{c:"ae",q:"L'astuce de reparamétrisation écrit :",o:["$z = \\mu + \\sigma \\odot \\varepsilon$, avec $\\varepsilon \\sim \\mathcal{N}(0, I)$","$z = \\mu \\cdot \\sigma$","$z = \\text{softmax}(\\mu)$","$z = x$"],a:0,e:"Le hasard est isolé dans ε : on peut rétropropager à travers μ et σ."},
{c:"ae",q:"La perte d'un VAE (ELBO à maximiser) contient :",o:["seulement l'erreur de reconstruction","un terme de reconstruction et une divergence KL entre q(z|x) et l'a priori p(z)","une perte adversariale","une entropie croisée de classes"],a:1,e:"$\\text{ELBO} = \\mathbb{E}_q[\\log p(x|z)] - \\text{KL}(q(z|x)\\,\\|\\,p(z))$."},
{c:"ae",q:"Le terme KL du VAE sert à :",o:["améliorer la netteté","rapprocher les distributions latentes de l'a priori, pour que l'espace latent soit régulier et échantillonnable","accélérer le décodeur","supprimer le bruit"],a:1,e:"Compromis : trop de poids sur la KL rend les reconstructions floues."},
{c:"ae",q:"Pour générer une nouvelle image avec un VAE entraîné :",o:["on encode une image de test","on tire $z \\sim \\mathcal{N}(0, I)$ et on le passe dans le décodeur","on utilise le discriminateur","on inverse l'encodeur"],a:1,e:"L'encodeur ne sert qu'à l'entraînement (et à l'inférence du latent)."},
{c:"ae",q:"Un défaut classique des images générées par un VAE simple :",o:["elles sont trop nettes","elles sont floues","elles sont toujours identiques","elles sont en noir et blanc"],a:1,e:"La perte de reconstruction (souvent L2) moyenne les possibilités. Les GAN et la diffusion produisent des images plus nettes."},
{c:"ae",q:"L'ELBO est appelée ainsi car elle est :",o:["une borne supérieure de la perte","une borne inférieure de la log-vraisemblance $\\log p(x)$","égale à la précision","une mesure de distance entre images"],a:1,e:"Evidence Lower BOund. Maximiser l'ELBO pousse la vraisemblance vers le haut. La même idée sert à dériver la perte des modèles de diffusion."},

// ---------- GAN ----------
{c:"gan",q:"Dans un GAN, le générateur G et le discriminateur D :",o:["coopèrent pour classer","s'opposent : D distingue vrai et faux, G cherche à tromper D","sont le même réseau","sont entraînés sur des labels"],a:1,e:"C'est un jeu minimax : $\\min_G \\max_D \\mathbb{E}[\\log D(x)] + \\mathbb{E}[\\log(1 - D(G(z)))]$."},
{c:"gan",q:"L'entrée du générateur est :",o:["une image réelle","un vecteur de bruit z tiré d'une loi simple","un label seulement","la sortie de D"],a:1,e:"G transforme ce bruit en échantillon. Dans un cGAN, on ajoute une condition (label, image…)."},
{c:"gan",q:"À G fixé, le discriminateur optimal vaut :",o:["0,5 partout","$p_{data}(x) / (p_{data}(x) + p_g(x))$","$p_g(x)$","1 partout"],a:1,e:"Quand $p_g = p_{data}$, il vaut 1/2 partout : il ne peut plus distinguer."},
{c:"gan",q:"Avec le discriminateur optimal, l'objectif de G revient à minimiser :",o:["l'erreur quadratique","la divergence de Jensen-Shannon entre $p_{data}$ et $p_g$","l'entropie croisée de classes","la KL de l'a priori"],a:1,e:"Le minimum global est atteint pour $p_g = p_{data}$."},
{c:"gan",q:"En pratique, au lieu de minimiser $\\log(1 - D(G(z)))$, G maximise souvent $\\log D(G(z))$ car :",o:["c'est plus rapide à calculer","le premier sature au début (gradient très faible quand D rejette facilement les faux)","cela supprime D","c'est imposé par PyTorch"],a:1,e:"C'est la version « non saturante » : même point fixe, mais des gradients utiles au début."},
{c:"gan",q:"L'effondrement de modes (mode collapse) :",o:["D devient parfait","G ne produit qu'une petite variété d'échantillons","les poids deviennent nuls","l'entraînement converge trop vite"],a:1,e:"G trouve quelques sorties qui trompent D et s'y limite."},
{c:"gan",q:"Pourquoi l'entraînement d'un GAN est-il instable ?",o:["Il n'utilise pas de gradient","On cherche un équilibre dans un jeu à deux joueurs, pas un minimum d'une seule fonction ; les mises à jour alternées peuvent osciller","Il n'a pas de fonction de perte","Il nécessite des labels"],a:1,e:"La descente de gradient stochastique alternée n'est pas garantie de converger vers l'équilibre."},
{c:"gan",q:"Un GAN conditionnel (cGAN) :",o:["n'utilise pas de bruit","donne une condition (par exemple la classe) à G et à D","n'a pas de discriminateur","génère uniquement du texte"],a:1,e:"On contrôle ce qui est généré, par exemple « un 7 »."},
{c:"gan",q:"Dans pix2pix (traduction d'images avec paires), le générateur est typiquement :",o:["un MLP","un U-Net","un RNN","un Transformer décodeur"],a:1,e:"Les connexions de saut du U-Net conservent la structure de l'image d'entrée."},
{c:"gan",q:"La cohérence cyclique (CycleGAN) impose :",o:["$G(x) = x$","$F(G(x)) \\approx x$ et $G(F(y)) \\approx y$","des paires d'images alignées","un seul générateur"],a:1,e:"Elle permet d'apprendre une traduction entre domaines sans paires (chevaux et zèbres)."},
{c:"gan",q:"CycleGAN se distingue de pix2pix car :",o:["il n'a pas de discriminateur","il n'a pas besoin de paires d'images alignées","il ne fonctionne que sur du texte","il est supervisé par des labels de classe"],a:1,e:"Deux générateurs, deux discriminateurs, et la perte de cohérence cyclique remplacent la supervision par paires."},
{c:"gan",q:"Une limite des GAN par rapport aux VAE :",o:["ils ne génèrent pas d'images","ils ne fournissent pas directement de vraisemblance ni d'encodeur","ils sont toujours flous","ils n'ont pas de paramètres"],a:1,e:"Le GAN apprend à échantillonner, pas à évaluer $p(x)$."},

// ---------- Diffusion ----------
{c:"diff",q:"Le processus direct (forward) d'un modèle de diffusion :",o:["débruite une image","ajoute progressivement du bruit gaussien jusqu'à obtenir du bruit pur","compresse l'image","entraîne le discriminateur"],a:1,e:"Il est fixé, sans paramètres appris."},
{c:"diff",q:"Le processus inverse :",o:["est fixé à la main","est appris : un réseau débruite pas à pas, du bruit vers une image","ajoute du bruit","n'existe qu'en théorie"],a:1,e:"C'est lui qui génère : on part de $x_T \\sim \\mathcal{N}(0, I)$."},
{c:"diff",q:"Grâce aux propriétés gaussiennes, on peut obtenir directement $x_t$ à partir de $x_0$ :",o:["$x_t = \\sqrt{\\bar\\alpha_t}\\, x_0 + \\sqrt{1-\\bar\\alpha_t}\\, \\varepsilon$","$x_t = x_0 + t$","$x_t = \\varepsilon$","il faut toujours simuler les t étapes"],a:0,e:"Cela rend l'entraînement efficace : on tire un t au hasard et on bruite en une seule fois."},
{c:"diff",q:"Dans la formulation DDPM la plus courante, le réseau est entraîné à prédire :",o:["la classe de l'image","le bruit ε ajouté, avec une perte quadratique","le discriminateur","la moyenne du dataset"],a:1,e:"Perte simplifiée : $\\| \\varepsilon - \\varepsilon_\\theta(x_t, t) \\|^2$, dérivée de l'ELBO."},
{c:"diff",q:"Le réseau débruiteur reçoit en entrée :",o:["seulement $x_t$","$x_t$ et le pas de temps t (et une éventuelle condition)","seulement t","l'image originale $x_0$"],a:1,e:"Le niveau de bruit dépend de t ; le réseau doit le connaître. Architecture classique : un U-Net."},
{c:"diff",q:"Une limite des modèles de diffusion classiques :",o:["images floues","génération lente : beaucoup d'étapes de débruitage","ils ne peuvent pas être conditionnés","pas de fonction de perte"],a:1,e:"Chaque étape est un passage dans le réseau. D'où des échantillonneurs accélérés et le travail dans un espace latent."},
{c:"diff",q:"La guidance par classifieur (classifier guidance) :",o:["remplace le débruiteur","utilise le gradient d'un classifieur entraîné sur des images bruitées pour orienter la génération vers une classe","supprime le bruit","entraîne un GAN"],a:1,e:"On ajoute $\\nabla_x \\log p(y \\mid x_t)$, pondéré, à la direction de débruitage."},
{c:"diff",q:"La guidance sans classifieur (classifier-free guidance) :",o:["n'utilise aucun conditionnement","combine les prédictions conditionnelle et non conditionnelle d'un même modèle","utilise deux classifieurs","n'existe qu'en théorie"],a:1,e:"On entraîne le modèle en retirant parfois la condition, puis on extrapole entre les deux prédictions."},
{c:"diff",q:"Stable Diffusion (diffusion latente) fait la diffusion :",o:["directement sur les pixels","dans l'espace latent d'un autoencodeur, beaucoup plus petit","sur le texte","dans le discriminateur"],a:1,e:"Le décodeur de l'autoencodeur repasse en pixels à la fin. Cela réduit fortement le coût de calcul."},
{c:"diff",q:"Dans Stable Diffusion, le texte influence le débruiteur par :",o:["une concaténation au pixel","de l'attention croisée (cross-attention) avec les sorties d'un encodeur de texte","un label de classe","un discriminateur"],a:1,e:"Les requêtes viennent de l'image, les clés et valeurs du texte encodé."},
{c:"diff",q:"Stable Diffusion 3 remplace notamment le U-Net par :",o:["un RNN","une architecture Transformer (MMDiT) entraînée avec du rectified flow","un MLP","un GAN"],a:1,e:"Article « Scaling Rectified Flow Transformers for High-Resolution Image Synthesis » (2024)."},
{c:"diff",q:"Comme pour le VAE, la perte des modèles de diffusion se dérive de :",o:["la perte adversariale","une borne inférieure de la log-vraisemblance (ELBO)","l'entropie croisée de classes","la distance de Wasserstein"],a:1,e:"Le processus de diffusion est un modèle à variables latentes hiérarchique."},

// ---------- Attention et Transformers ----------
{c:"tr",q:"L'attention par produit scalaire calcule :",o:["$\\text{softmax}(QK^\\top/\\sqrt{d_k})\\,V$","$QKV$","$\\text{softmax}(V)\\,QK$","$\\sigma(Q + K)$"],a:0,e:"Chaque requête compare sa similarité à toutes les clés, puis fait une moyenne pondérée des valeurs."},
{c:"tr",q:"Pourquoi divise-t-on par $\\sqrt{d_k}$ ?",o:["Pour normaliser les valeurs","Pour éviter des produits scalaires trop grands qui saturent le softmax et écrasent les gradients","Pour réduire la mémoire","Pour rendre la matrice symétrique"],a:1,e:"La variance de $q^\\top k$ croît avec $d_k$ si les composantes sont de variance 1."},
{c:"tr",q:"Chaque ligne de la matrice d'attention (après softmax) :",o:["somme à 0","somme à 1","est nulle","vaut la dimension d"],a:1,e:"Ce sont les poids d'une moyenne pondérée des valeurs."},
{c:"tr",q:"Le masque causal dans un décodeur (type GPT) :",o:["masque le padding","empêche une position de regarder les positions futures","masque 15 % des tokens","supprime les têtes d'attention"],a:1,e:"On met $-\\infty$ au-dessus de la diagonale avant le softmax : la génération reste autoregressive."},
{c:"tr",q:"Le masque de padding :",o:["empêche de voir le futur","met à 0 les poids d'attention vers les positions de remplissage","masque les mots rares","sert uniquement au décodeur"],a:1,e:"Sans lui, la représentation d'une phrase dépendrait de la longueur du padding dans le batch."},
{c:"tr",q:"Sans encodage de position, la self-attention est :",o:["sensible à l'ordre","invariante par permutation des tokens (elle voit un ensemble)","impossible à calculer","limitée à 512 tokens"],a:1,e:"Permuter les tokens permute simplement les sorties : l'ordre est perdu. On ajoute donc la position à l'embedding."},
{c:"tr",q:"L'attention multi-têtes :",o:["calcule plusieurs attentions en parallèle sur des sous-espaces, puis concatène","répète la même attention","remplace la couche feed-forward","n'a pas de paramètres"],a:0,e:"Chaque tête peut se spécialiser sur un type de relation."},
{c:"tr",q:"Nombre de paramètres de nn.MultiheadAttention(64, 4) :",o:["16 384","16 640","4 096","65 536"],a:1,e:"Q, K, V : $3 \\times (64 \\times 64 + 64) = 12\\,480$, plus la projection de sortie $64 \\times 64 + 64 = 4\\,160$. Total 16 640, indépendant du nombre de têtes."},
{c:"tr",q:"Le coût de la self-attention en fonction de la longueur L de la séquence est :",o:["$O(L)$","$O(L^2)$","$O(\\log L)$","$O(1)$"],a:1,e:"La matrice d'attention est L × L. C'est la principale limite pour les très longues séquences."},
{c:"tr",q:"Principal avantage d'un Transformer sur un RNN à l'entraînement :",o:["moins de paramètres","toutes les positions sont traitées en parallèle","coût linéaire en longueur","pas besoin de données"],a:1,e:"Un RNN doit attendre $h_{t-1}$ pour calculer $h_t$."},
{c:"tr",q:"Entre deux tokens éloignés de 100 positions, le chemin d'information est :",o:["de longueur 100 dans un Transformer","de longueur 1 dans un Transformer, d'environ 100 pas dans un RNN","le même dans les deux","impossible dans un RNN"],a:1,e:"L'attention relie directement toutes les paires de positions, ce qui aide les dépendances longues."},
{c:"tr",q:"Un bloc d'encodeur Transformer contient :",o:["self-attention, puis feed-forward, chacun avec connexion résiduelle et normalisation de couche","une convolution et un pooling","un LSTM","un discriminateur"],a:0,e:"Les connexions résiduelles et la LayerNorm reprennent les idées de ResNet et de la normalisation."},
{c:"tr",q:"Dans l'attention croisée (encodeur-décodeur) :",o:["Q, K et V viennent du décodeur","les requêtes viennent du décodeur, les clés et valeurs de l'encodeur","tout vient de l'encodeur","il n'y a pas de softmax"],a:1,e:"C'est aussi le mécanisme de conditionnement par le texte dans Stable Diffusion."},
{c:"tr",q:"GPT et BERT diffèrent principalement par :",o:["le nombre de couches","GPT est un décodeur causal (génération), BERT un encodeur bidirectionnel (représentation)","BERT n'utilise pas l'attention","GPT n'a pas d'embeddings"],a:1,e:"Ils viennent tous deux de l'architecture Transformer de 2017."},
{c:"tr",q:"Avec une valeur $-\\infty$ dans un score avant softmax, le poids d'attention correspondant vaut :",o:["$-\\infty$","0","1","indéfini"],a:1,e:"$e^{-\\infty} = 0$. C'est ainsi qu'on implémente les masques."},
{c:"tr",q:"Pour adapter un Transformer à une série temporelle (comme HAR), on peut :",o:["projeter chaque pas de temps en un vecteur de dimension d, ajouter une position et un token [CLS]","convertir la série en image","supprimer la dimension temporelle","utiliser un softmax sur les capteurs"],a:0,e:"Chaque pas devient un « token ». C'est le principe de l'examen blanc B."},

// ---------- BERT et transfer learning ----------
{c:"bert",q:"Pourquoi BERT n'a-t-il pas besoin de décodeur pour classer une phrase ?",o:["Il génère la phrase","La sortie est une seule étiquette, pas une séquence à générer","Le décodeur est intégré au tokenizer","Il n'utilise pas d'attention"],a:1,e:"Un encodeur produit des représentations ; une couche linéaire suffit pour classer."},
{c:"bert",q:"Pour classer une phrase avec BERT, on utilise généralement :",o:["la moyenne des embeddings d'entrée","le vecteur de sortie à la position [CLS]","le vecteur de [SEP]","le dernier token"],a:1,e:"Une couche linéaire sur ce vecteur donne les logits."},
{c:"bert",q:"Pourquoi [CLS], placé en première position, peut-il résumer toute la phrase ?",o:["Il est le plus fréquent","Dans un encodeur bidirectionnel, il calcule son vecteur par attention sur tous les tokens, à chaque couche","Il contient le label","Il est figé"],a:1,e:"La position ne limite pas ce qu'il voit, contrairement à un modèle causal."},
{c:"bert",q:"Le tokenizer de BERT découpe le texte en :",o:["caractères","sous-mots (WordPiece)","phrases","octets uniquement"],a:1,e:"Un mot rare est découpé en morceaux connus, ce qui limite le vocabulaire et les mots inconnus."},
{c:"bert",q:"L'embedding d'entrée de BERT est la somme :",o:["du token et de la position (et du segment)","du token seulement","de la position seulement","du label et du token"],a:0,e:"La position est indispensable puisque l'attention seule ignore l'ordre."},
{c:"bert",q:"Le pré-entraînement MLM de BERT consiste à :",o:["prédire le mot suivant","prédire environ 15 % de tokens masqués à partir du contexte des deux côtés","classer des sentiments","traduire"],a:1,e:"Le texte fournit lui-même les réponses : c'est de l'apprentissage auto-supervisé, sans labels humains."},
{c:"bert",q:"Parmi les 15 % de tokens choisis pour le MLM :",o:["tous sont remplacés par [MASK]","80 % par [MASK], 10 % par un token aléatoire, 10 % laissés tels quels","50 % sont supprimés","aucun n'est modifié"],a:1,e:"Cela évite un décalage avec le fine-tuning, où [MASK] n'apparaît jamais."},
{c:"bert",q:"La tâche NSP (next sentence prediction) entraîne BERT à :",o:["générer la phrase suivante","prédire, via [CLS], si la phrase B suit vraiment la phrase A","compter les phrases","traduire la phrase B"],a:1,e:"Elle a contribué à faire de [CLS] un résumé de la paire de phrases."},
{c:"bert",q:"Fine-tuning complet contre encodeur gelé :",o:["identiques","complet : tous les poids sont entraînés ; gelé : seule la tête linéaire est entraînée","gelé : tous les poids sont entraînés","complet : aucun poids n'est entraîné"],a:1,e:"Gelé : peu de paramètres et rapide, mais l'encodeur ne s'adapte pas. Complet : souvent meilleur, plus coûteux."},
{c:"bert",q:"Pour geler l'encodeur en PyTorch :",o:["model.eval()","for p in encoder.parameters(): p.requires_grad = False","torch.no_grad() sur tout l'entraînement","supprimer l'encodeur"],a:1,e:"Et l'optimiseur ne reçoit que les paramètres entraînables. model.eval() ne gèle rien."},
{c:"bert",q:"Pourquoi utilise-t-on un petit taux d'apprentissage (par exemple 2e-5 à 5e-5) pour le fine-tuning complet ?",o:["Pour aller plus vite","Pour ne pas détruire ce que le pré-entraînement a appris","Parce que BERT n'a pas de gradient","Parce que le batch est petit"],a:1,e:"Un grand taux peut provoquer un oubli catastrophique des représentations pré-entraînées."},
{c:"bert",q:"Le pré-entraînement aide surtout :",o:["quand les données labellisées sont rares","quand on a des millions d'exemples labellisés","jamais","uniquement en vision"],a:0,e:"Le modèle connaît déjà la langue ; il ne reste qu'à apprendre la tâche. L'avantage diminue quand les labels abondent."},
{c:"bert",q:"Dans le TP4-2, les vecteurs GloVe sont :",o:["contextuels","pré-entraînés et non contextuels : un seul vecteur par mot, quel que soit le sens","appris pendant le TP","des sorties de BERT"],a:1,e:"C'est déjà du transfer learning. Le GRU bidirectionnel ajoute le contexte ; BERT donne directement des vecteurs contextuels."},
{c:"bert",q:"Dans le TP2 (chats contre chiens), réutiliser un réseau pré-entraîné sur 10 classes est un exemple de :",o:["data augmentation","transfer learning","dropout","batch norm"],a:1,e:"On remplace la tête de classification et on réentraîne tout ou partie du réseau."},

// ---------- Méthodologie ----------
{c:"meth",q:"Le jeu de validation sert à :",o:["entraîner le modèle","choisir les hyperparamètres, l'epoch et le modèle","mesurer la performance finale","augmenter les données"],a:1,e:"Le test est réservé à une seule évaluation finale, une fois tous les choix figés."},
{c:"meth",q:"Pourquoi ne regarde-t-on le test qu'une fois ?",o:["Il est trop long à calculer","Chaque décision prise au vu du test adapte le modèle au test : le score devient optimiste","Le test contient des erreurs","Par convention seulement"],a:1,e:"C'est une forme de fuite de données."},
{c:"meth",q:"Dans HAR, pourquoi faire la validation par sujet plutôt qu'un random_split ligne à ligne ?",o:["Pour aller plus vite","Les fenêtres d'une même personne se chevauchent : un random_split met des quasi-doublons en train et en validation","Pour équilibrer les classes","Parce que random_split n'existe pas"],a:1,e:"Le test contient des personnes jamais vues ; la validation doit mesurer la même chose."},
{c:"meth",q:"La loss d'entraînement baisse, celle de validation remonte après l'epoch 6 :",o:["sous-apprentissage","surapprentissage","taux d'apprentissage trop petit","bug de données"],a:1,e:"Parade : garder la meilleure epoch en validation (early stopping), régulariser, augmenter les données."},
{c:"meth",q:"Les deux loss restent hautes et proches :",o:["surapprentissage","sous-apprentissage : modèle trop simple ou pas assez entraîné","fuite de données","modèle parfait"],a:1,e:"Il faut plus de capacité, plus d'epochs ou un meilleur taux d'apprentissage."},
{c:"meth",q:"Deux modèles : 0,85 ± 0,02 et 0,86 ± 0,02 sur 3 seeds. Conclusion :",o:["le second est meilleur","pas de différence détectable","le premier est meilleur","il faut regarder le test pour trancher"],a:1,e:"L'écart (0,01) est inférieur à la variabilité entre seeds."},
{c:"meth",q:"Que fait varier la seed ?",o:["Rien d'important","L'initialisation, l'ordre des mini-batchs, le dropout et éventuellement le sous-échantillon","Seulement le jeu de test","Le nombre de couches"],a:1,e:"On rapporte moyenne ± écart-type sur plusieurs seeds pour juger si une différence est réelle."},
{c:"meth",q:"Une comparaison juste entre deux architectures exige :",o:["des données différentes pour chacune","les mêmes splits, le même budget, le même critère de sélection, et un seul facteur qui change","le meilleur run de chacune","de régler davantage la méthode qu'on préfère"],a:1,e:"Idéalement aussi un nombre de paramètres comparable, comme le GRU à 150 unités face au Transformer dans l'examen blanc B."},
{c:"meth",q:"Le early stopping consiste à :",o:["arrêter dès que la loss d'entraînement baisse","garder les poids de la meilleure epoch en validation","arrêter au premier epoch","supprimer la validation"],a:1,e:"C'est une forme de régularisation, avec la même règle pour tous les modèles comparés."},
{c:"meth",q:"Pour 6 classes équilibrées, la métrique principale raisonnable est :",o:["l'accuracy","la loss d'entraînement","le nombre de paramètres","le temps de calcul"],a:0,e:"Si les classes sont déséquilibrées : F1 macro ou accuracy équilibrée."},
{c:"meth",q:"Un modèle scratch et un GRU restent proches de 50 % avec 100 exemples sur une tâche binaire. Il faut :",o:["conclure à un bug","vérifier que la loss d'entraînement baisse, puis l'écrire comme un résultat : trop peu de données pour apprendre sans pré-entraînement","cacher ce résultat","augmenter le test"],a:1,e:"Un résultat inattendu s'analyse et se rapporte honnêtement ; cela rapporte plus de points qu'un résultat « conforme » mal analysé."},
{c:"meth",q:"La normalisation des données doit être apprise :",o:["sur train + validation + test","sur le train uniquement, puis appliquée telle quelle aux autres","sur le test","séparément sur chaque jeu"],a:1,e:"Sinon, les statistiques du test influencent le modèle."},

// ---------- Distillation (knowledge distillation) ----------
{c:"dist",q:"La knowledge distillation consiste à :",o:["entraîner un petit modèle (élève) à reproduire les sorties d'un grand modèle (professeur)","fusionner les poids de deux modèles","supprimer les neurones inutiles d'un réseau","réduire la précision numérique des poids"],a:0,e:"Hinton, Vinyals et Dean (2015). L'élève apprend sur les probabilités du professeur, pas seulement sur les labels. Supprimer des neurones, c'est l'élagage (pruning) ; réduire la précision, la quantification."},
{c:"dist",q:"Le but principal de la distillation est généralement :",o:["obtenir un modèle plus petit et plus rapide qui garde l'essentiel des performances","augmenter la taille du modèle","remplacer la descente de gradient","se passer de données"],a:0,e:"On cherche un modèle déployable (mobile, faible latence, coût réduit) avec une perte de performance limitée."},
{c:"dist",q:"La motivation d'origine de l'article de Hinton et al. (2015) était notamment de :",o:["compresser un ensemble de modèles en un seul modèle","entraîner des GAN","remplacer les CNN","traduire des textes"],a:0,e:"Un ensemble est précis mais coûteux à déployer. La distillation transfère sa connaissance dans un modèle unique."},
{c:"dist",q:"Les « soft targets » sont :",o:["les labels one-hot","les distributions de probabilités produites par le professeur","les poids du professeur","des labels bruités au hasard"],a:1,e:"Elles indiquent aussi quelles mauvaises classes le professeur juge plausibles, ce qu'un label one-hot ne dit pas."},
{c:"dist",q:"Ce que Hinton appelle la « dark knowledge » est :",o:["les poids cachés du professeur","les probabilités relatives que le professeur donne aux classes incorrectes","les données d'entraînement secrètes","la couche de sortie"],a:1,e:"Un « 2 » manuscrit qui ressemble un peu à un « 3 » reçoit une petite probabilité de 3 : information absente du label."},
{c:"dist",q:"Le softmax avec température T s'écrit :",o:["$p_i = \\exp(z_i/T) / \\sum_j \\exp(z_j/T)$","$p_i = \\exp(T z_i)$","$p_i = z_i / T$","$p_i = \\sigma(z_i) \\cdot T$"],a:0,e:"T = 1 donne le softmax habituel. Diviser les logits par T > 1 adoucit la distribution."},
{c:"dist",q:"Augmenter la température T (T > 1) :",o:["rend la distribution plus piquée","rend la distribution plus douce (plus uniforme)","ne change rien","inverse les classes"],a:1,e:"Les écarts entre logits sont réduits : les petites probabilités des classes incorrectes deviennent visibles et portent du signal."},
{c:"dist",q:"Quand $T \\to \\infty$, le softmax tend vers :",o:["une distribution one-hot","une distribution uniforme","zéro partout","la classe la plus probable"],a:1,e:"Tous les logits divisés par T tendent vers 0 : toutes les classes deviennent également probables."},
{c:"dist",q:"Quand $T \\to 0$, le softmax tend vers :",o:["une distribution uniforme","un one-hot sur la classe de plus grand logit","une loi normale","une moyenne des logits"],a:1,e:"Les écarts sont amplifiés à l'extrême."},
{c:"dist",q:"Logits [2, 1, 0]. Avec T = 1, la probabilité de la première classe vaut environ :",o:["0,51","0,67","0,33","0,90"],a:1,e:"$e^2 / (e^2 + e + 1) \\approx 7{,}39 / 11{,}1 \\approx 0{,}67$."},
{c:"dist",q:"Mêmes logits [2, 1, 0] avec T = 2. La probabilité de la première classe devient environ :",o:["0,67","0,51","0,90","0,33"],a:1,e:"Logits divisés par 2 : [1 ; 0,5 ; 0]. $e / (e + e^{0{,}5} + 1) \\approx 2{,}72 / 5{,}37 \\approx 0{,}51$. La distribution est plus douce."},
{c:"dist",q:"La perte de distillation classique combine :",o:["une entropie croisée sur les vrais labels et une divergence KL entre sorties adoucies du professeur et de l'élève","une erreur quadratique sur les poids","une perte adversariale","l'entropie croisée sur les labels seule"],a:0,e:"$\\mathcal{L} = \\alpha\\, \\text{CE}(y, p_S) + (1-\\alpha)\\, T^2\\, \\text{KL}(p_T^{(T)} \\,\\|\\, p_S^{(T)})$. Le poids α équilibre les deux termes."},
{c:"dist",q:"Pourquoi multiplie-t-on le terme de distillation par $T^2$ ?",o:["Pour accélérer l'inférence","Parce que les gradients du terme adouci sont d'ordre $1/T^2$ : on garde l'équilibre avec le terme sur les vrais labels quand T change","Pour normaliser les poids","Par convention, sans raison"],a:1,e:"Sans ce facteur, augmenter T réduirait fortement l'influence du professeur."},
{c:"dist",q:"Le gradient du terme adouci par rapport au logit $z_i$ de l'élève est proportionnel à :",o:["$(q_i - p_i)/T$, avec q l'élève et p le professeur","$z_i^2$","$T \\cdot z_i$","0"],a:0,e:"C'est l'analyse de Hinton et al. : d'où le facteur 1/T, compensé par $T^2$ dans la perte."},
{c:"dist",q:"À haute température et avec des logits centrés, faire correspondre les soft targets revient approximativement à :",o:["faire correspondre les logits (erreur quadratique entre logits)","faire correspondre les labels one-hot","ignorer le professeur","maximiser l'entropie"],a:0,e:"C'est le lien avec Caruana et al. (2006), qui faisaient régresser directement les logits."},
{c:"dist",q:"À quelle température l'élève prédit-il une fois déployé ?",o:["à la température élevée de l'entraînement","T = 1, le softmax habituel","T = 0","une température aléatoire"],a:1,e:"La température élevée ne sert qu'à transférer la connaissance pendant l'entraînement."},
{c:"dist",q:"En PyTorch, nn.KLDivLoss attend :",o:["des probabilités pour l'entrée et la cible","les log-probabilités de l'élève (log_softmax) en entrée et les probabilités du professeur (softmax) en cible","des logits bruts des deux modèles","des labels entiers"],a:1,e:"Piège classique : passer des probabilités au lieu de log-probabilités donne une perte fausse sans aucune erreur. On utilise souvent reduction='batchmean'."},
{c:"dist",q:"Pendant une distillation classique, le professeur doit être :",o:["entraîné en même temps que l'élève","figé : en mode eval et sous torch.no_grad()","réinitialisé à chaque epoch","supprimé"],a:1,e:"Le mode eval coupe aussi le dropout, qui rendrait ses cibles bruitées ; no_grad évite de calculer des gradients inutiles."},
{c:"dist",q:"Pourquoi un élève apprend-il souvent mieux avec les soft targets qu'avec les seuls labels ?",o:["Il voit plus d'images","Chaque exemple porte plus d'information (similarités entre classes), ce qui régularise et réduit la variance des gradients","Les soft targets sont toujours justes","Le professeur triche"],a:1,e:"Hinton et al. montrent qu'un élève sur soft targets généralise bien même avec peu de données, là où les labels durs le font surapprendre."},
{c:"dist",q:"L'ensemble de transfert (transfer set) utilisé pour distiller :",o:["doit être exactement le jeu d'entraînement du professeur","peut contenir des données non labellisées, puisque le professeur fournit les cibles","doit être le jeu de test","doit être généré au hasard"],a:1,e:"C'est un intérêt majeur : on peut exploiter des données non annotées."},
{c:"dist",q:"Selon ce qui est transféré, on distingue la distillation :",o:["par réponses (sorties), par caractéristiques (couches intermédiaires) et par relations (entre exemples)","par CPU, GPU et TPU","supervisée, non supervisée et par renforcement","linéaire, quadratique et cubique"],a:0,e:"Classification de la revue de Gou et al. (2021)."},
{c:"dist",q:"FitNets (Romero et al., 2015) introduit :",o:["la distillation de couches intermédiaires (« hints ») vers un élève plus fin et plus profond","l'attention multi-têtes","le softmax avec température","la quantification"],a:0,e:"L'élève imite aussi une représentation intermédiaire du professeur, pas seulement sa sortie."},
{c:"dist",q:"Dans FitNets, pourquoi ajoute-t-on une petite couche de régression ?",o:["Pour classer","Parce que la couche de l'élève et la couche « hint » du professeur n'ont pas la même dimension","Pour supprimer le professeur","Pour augmenter la température"],a:1,e:"Elle projette la représentation de l'élève dans l'espace du professeur avant de calculer l'erreur."},
{c:"dist",q:"L'« attention transfer » (Zagoruyko et Komodakis, 2017) fait imiter à l'élève :",o:["les labels","les cartes d'attention spatiale du professeur, c'est-à-dire où il « regarde » dans l'image","les poids du professeur","la température"],a:1,e:"C'est une distillation par caractéristiques, appliquée aux CNN."},
{c:"dist",q:"La distillation relationnelle (Park et al., 2019) transfère :",o:["les sorties de chaque exemple pris isolément","les relations entre exemples, comme les distances et les angles dans l'espace des représentations","les hyperparamètres","le jeu de données"],a:1,e:"L'élève doit reproduire la géométrie que le professeur construit entre les exemples."},
{c:"dist",q:"DistilBERT est :",o:["un BERT plus grand","une version distillée de BERT avec 6 couches au lieu de 12","un modèle de vision","un GAN pour le texte"],a:1,e:"Sanh et al. (2019) : environ 40 % de paramètres en moins et 60 % plus rapide, en gardant environ 97 % des performances sur GLUE."},
{c:"dist",q:"La perte d'entraînement de DistilBERT combine :",o:["l'entropie croisée MLM seule","une perte de distillation sur les sorties, la perte MLM et une perte cosinus entre états cachés","une perte adversariale","une perte de traduction"],a:1,e:"La perte cosinus aligne la direction des représentations cachées de l'élève et du professeur."},
{c:"dist",q:"Comment DistilBERT est-il initialisé ?",o:["au hasard","en reprenant une couche sur deux du BERT professeur","avec les poids de GPT","avec des zéros"],a:1,e:"Cette initialisation exploite la structure commune et accélère l'apprentissage."},
{c:"dist",q:"TinyBERT se distingue par :",o:["une distillation couche par couche : embeddings, matrices d'attention, états cachés et sorties","l'absence de professeur","l'utilisation d'un RNN","une seule couche"],a:0,e:"Il procède en deux temps : distillation générale sur un grand corpus, puis distillation spécifique à la tâche."},
{c:"dist",q:"L'écart de capacité (capacity gap) désigne le fait que :",o:["un professeur beaucoup plus gros n'est pas toujours un meilleur professeur pour un très petit élève","l'élève a toujours plus de paramètres","la température est trop élevée","le GPU manque de mémoire"],a:0,e:"Mirzadeh et al. (2020) proposent un professeur intermédiaire (teacher assistant) pour combler l'écart."},
{c:"dist",q:"Les « born-again networks » (Furlanello et al., 2018) montrent que :",o:["un élève de même architecture que le professeur peut le dépasser","la distillation ne marche qu'avec de petits élèves","il faut toujours réentraîner de zéro","la température doit valoir 1"],a:0,e:"La distillation agit aussi comme une régularisation, pas seulement comme une compression."},
{c:"dist",q:"L'auto-distillation (self-distillation) :",o:["utilise le modèle lui-même (une version antérieure, des couches profondes) comme professeur","n'utilise aucune donnée","nécessite deux GPU","supprime l'élève"],a:0,e:"Par exemple, les couches profondes guident les couches peu profondes, ou une génération entraînée guide la suivante."},
{c:"dist",q:"Le deep mutual learning (Zhang et al., 2018) :",o:["fait apprendre plusieurs élèves ensemble, chacun imitant les autres, sans professeur pré-entraîné","distille un seul professeur figé","utilise un discriminateur","supprime la perte supervisée"],a:0,e:"C'est une distillation en ligne : tous les modèles apprennent en même temps."},
{c:"dist",q:"Distillation hors ligne et en ligne :",o:["hors ligne : professeur pré-entraîné et figé ; en ligne : professeur et élève apprennent ensemble","c'est la même chose","hors ligne : sans données","en ligne : sans élève"],a:0,e:"Le cas classique de Hinton est hors ligne."},
{c:"dist",q:"La distillation au niveau de la séquence (Kim et Rush, 2016), en traduction :",o:["entraîne l'élève sur les phrases générées par le professeur (beam search)","fait correspondre chaque poids","utilise des images","supprime le décodeur"],a:0,e:"Plutôt que d'imiter la distribution mot par mot, l'élève apprend les sorties complètes du professeur."},
{c:"dist",q:"Pour distiller un grand modèle de langage, une pratique courante est :",o:["faire générer au professeur beaucoup de réponses, puis affiner l'élève dessus","copier les poids du professeur","augmenter la température à l'inférence","supprimer le tokenizer"],a:0,e:"Exemple : les modèles DeepSeek-R1-Distill, des Qwen et Llama plus petits affinés sur des raisonnements générés par DeepSeek-R1."},
{c:"dist",q:"La KL « directe » KL(professeur ‖ élève) a tendance à :",o:["couvrir toutes les zones de probabilité du professeur (mean-seeking)","se concentrer sur un seul mode (mode-seeking)","être toujours nulle","ignorer le professeur"],a:0,e:"La KL inverse KL(élève ‖ professeur) cherche plutôt un mode ; MiniLLM (2023) l'utilise pour les modèles génératifs."},
{c:"dist",q:"Le label smoothing et la distillation ont en commun :",o:["d'entraîner sur des cibles adoucies plutôt que des one-hot","d'utiliser un professeur","d'augmenter la taille du modèle","de supprimer l'entropie croisée"],a:0,e:"Différence : le label smoothing répartit la masse uniformément, le professeur la répartit de façon informative."},
{c:"dist",q:"Müller et al. (2019) observent qu'un professeur entraîné avec label smoothing :",o:["distille moins bien, car il efface une partie de l'information sur les similarités entre classes","distille toujours mieux","n'a pas de logits","ne peut pas servir"],a:0,e:"Le label smoothing resserre les représentations de chaque classe et appauvrit la dark knowledge."},
{c:"dist",q:"Distillation, élagage (pruning) et quantification :",o:["sont des méthodes de compression différentes, souvent combinables","sont la même méthode","s'excluent mutuellement","ne concernent que les CNN"],a:0,e:"Distiller : un nouveau modèle plus petit. Élaguer : retirer des poids. Quantifier : stocker les poids en basse précision (int8…)."},
{c:"dist",q:"Dans $\\alpha\\, \\text{CE} + (1-\\alpha)\\, T^2\\, \\text{KL}$, le coefficient α :",o:["règle l'équilibre entre les vrais labels et l'imitation du professeur","fixe la température","fixe le taux d'apprentissage","compte les couches"],a:0,e:"Hinton et al. obtenaient de bons résultats avec un poids nettement plus faible sur le terme des vrais labels."},
{c:"dist",q:"Si le professeur se trompe souvent sur une classe, l'élève distillé :",o:["corrige automatiquement l'erreur","risque d'hériter de l'erreur, d'où l'intérêt de garder un terme sur les vrais labels","n'est pas affecté","devient plus gros"],a:1,e:"L'élève imite le professeur, défauts compris."},
{c:"dist",q:"La distillation sans données (data-free) :",o:["synthétise des entrées à partir du professeur (par exemple avec un générateur), faute d'accès aux données d'origine","n'a besoin ni de professeur ni d'élève","utilise uniquement le jeu de test","est impossible"],a:0,e:"Utile quand les données d'origine sont privées ou indisponibles."},
{c:"dist",q:"Interroger un modèle propriétaire pour entraîner un modèle imitateur s'apparente à :",o:["de l'extraction de modèle, encadrée par les conditions d'utilisation du fournisseur","de la quantification","de l'élagage","de la normalisation"],a:0,e:"La technique est la même que la distillation ; la question devient juridique et éthique."},
{c:"dist",q:"Un BERT distillé en 6 couches au lieu de 12 est plus rapide surtout parce que :",o:["les couches d'un Transformer se calculent l'une après l'autre : deux fois moins de couches, environ deux fois moins de calcul","il traite moins de tokens","il n'a plus d'attention","il est quantifié"],a:0,e:"La profondeur pèse directement sur la latence ; réduire la largeur aide moins sur GPU."}
];
